// Leest de zoekvraag uit de webhook-body, valideert 'top', en schrijft de
// query naar een tijdelijk bestand. Zo hoeft de query niet shell-escaped te
// worden: de Execute Command-node pipet het bestand via stdin naar het
// Python-script (kennisbank_query.py --stdin).
const body = ($input.first() && $input.first().json && $input.first().json.body) || {};
const query = String(body.query || '').trim();
if (!query) {
  throw new Error('Geen zoekvraag meegegeven. Stuur een JSON-body met veld "query".');
}

let top = parseInt(body.top, 10);
if (!Number.isFinite(top) || top < 1) top = 5;
if (top > 10) top = 10;

const fs = require('fs');
const execId = String($execution.id || 'single').replace(/[^0-9A-Za-z_-]/g, '_').slice(0, 32);
const queryFile = `/tmp/kb_query_${execId}_${Date.now()}.txt`;
fs.writeFileSync(queryFile, query, 'utf8');

return { json: { query, top, queryFile } };

// Parseert de JSON die kennisbank_query.py op stdout zet en bouwt de
// webhook-respons. Ruimt het tijdelijke query-bestand op.
const stdout = String($json.stdout || '');
const stderr = String($json.stderr || '');

try {
  const f = $('Prepare Query').first() && $('Prepare Query').first().json.queryFile;
  if (f) require('fs').unlinkSync(f);
} catch (_) { /* best-effort opruimen */ }

let parsed = null;
try {
  parsed = JSON.parse(stdout.trim());
} catch (_) {
  const m = stdout.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (_) {} }
}

if (!parsed || typeof parsed !== 'object') {
  throw new Error(
    `Kennisbank gaf geen geldige JSON terug. stdout=${stdout.slice(0, 300)} | stderr=${stderr.slice(0, 300)}`
  );
}

const bronnen = Array.isArray(parsed.bronnen) ? parsed.bronnen : [];
return [{
  json: {
    success: true,
    query: String(parsed.query || ''),
    count: bronnen.length,
    bronnen: bronnen.map((b) => ({
      score: typeof b.score === 'number' ? b.score : 0,
      titel: String(b.titel || ''),
      bron: String(b.bron || ''),
      artikel: String(b.artikel || ''),
      url: String(b.url || ''),
      tekst: String(b.tekst || ''),
    })),
  },
}];
